using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
namespace Ara {
 public partial class MainForm {
  public void ApplySatisfaction(decimal value){var sel=Board.Selection;if(sel==null||sel.Lane!=1)return;Change(()=>GridEngine.SetScore(Day.Records,Board.TimeAt(sel.First),sel.Count,value,true));}
  void ResizeCells(ResizeRequest e){Change(()=>{var list=e.Lane==0?GridPlan.DisplayBlocks.Select(x=>x.Copy()).ToList():Day.Records;BlockTools.Resize(list,e.Id,e.Start,e.Count,Day.Wake.Date,e.Lane==0);if(e.Lane==0)Day.GridBase=list;});Board.Focus();}
  void ShowLengthMenu(CellSelection sel){var source=Board.At(sel.Lane,sel.First);if(source==null||source.Category=="기상")return;using(var f=new Form{Text="블록 길이 조절 · 10분씩",Width=380,Height=220,StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Bg}){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12)};f.Controls.Add(panel);var range=Theme.Label(source.Start.ToString("HH:mm")+"–"+source.End.ToString("HH:mm"));range.Width=320;range.Height=35;panel.Controls.Add(range);foreach(string edge in new[]{"start","end"})foreach(int step in new[]{-1,1}){string side=edge;int amount=step;panel.Controls.Add(Theme.Button((side=="start"?"시작":"종료")+(amount<0?" −10분":" +10분"),(s,e)=>{var current=Board.At(sel.Lane,Board.Selection==null?sel.First:Board.Selection.First);if(current==null)current=source;var selection=BlockTools.Clamp(sel.Lane==0?GridPlan.DisplayBlocks:Day.Records,current,sel.Lane,side,Board.Index(side=="start"?current.Start:current.End.AddMinutes(-10))+amount,Day.Wake.Date);ResizeCells(new ResizeRequest{Lane=sel.Lane,Id=current.Id,Start=Board.TimeAt(selection.First),Count=selection.Count});Board.SetSelection(selection);range.Text=Board.TimeAt(selection.First).ToString("HH:mm")+"–"+Board.TimeAt(selection.Last+1).ToString("HH:mm");}));}Theme.Apply(f);f.ShowDialog(this);}}
  void ManageCategories(){using(var editor=new CategoryEditor(Data)){if(editor.ShowDialog(this)==DialogResult.OK)Change(()=>Data.CategorySettings=editor.Result);}}
 }
 public class CategoryEditor:Form {
  public List<CategoryDefinition> Result;DataGridView grid;State draft;
  public CategoryEditor(State state){draft=Store.Clone(state);CategoryCatalog.Ensure(draft);Text="카테고리 관리 · 숨겨도 과거 기록은 유지됩니다";Size=new Size(620,550);StartPosition=FormStartPosition.CenterParent;BackColor=Theme.Bg;grid=Theme.Grid();grid.AllowUserToAddRows=false;grid.Columns.Add("key","번호");grid.Columns[0].Visible=false;grid.Columns.Add("label","이름");grid.Columns.Add("color","색상 #RRGGBB");grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="hidden",HeaderText="숨기기"});foreach(var c in draft.CategorySettings.Where(x=>!x.deleted))grid.Rows.Add(c.name,c.label,c.color,c.hidden);Controls.Add(grid);var tools=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=145};Controls.Add(tools);tools.Controls.Add(Theme.Button("새 카테고리",(s,e)=>grid.Rows.Add("c_"+Guid.NewGuid().ToString("N"),"새 카테고리","#59836d",false)));tools.Controls.Add(Theme.Button("삭제",(s,e)=>{if(grid.CurrentRow==null)return;string key=Convert.ToString(grid.CurrentRow.Cells[0].Value);var category=draft.CategorySettings.Find(x=>x.name==key);if(category!=null){category.deleted=true;category.hidden=true;}grid.Rows.Remove(grid.CurrentRow);}));foreach(string hex in new[]{"#F2B8B5","#F4C7A1","#F3D990","#DDE5A8","#B9DDC7","#AFE0DA","#B8D8EE","#BDCBED","#D0C1ED","#E7BDDA","#D8C8BA","#C9D4D8"}){string chosen=hex;var swatch=new Button{Text="",Width=27,Height=27,BackColor=ColorTranslator.FromHtml(hex),FlatStyle=FlatStyle.Flat,Tag="pastel",AccessibleName="파스텔 "+hex};swatch.Click+=(s,e)=>{if(grid.CurrentRow!=null)grid.CurrentRow.Cells[2].Value=chosen;};tools.Controls.Add(swatch);}tools.Controls.Add(Theme.Button("색상 선택",(s,e)=>{if(grid.CurrentRow==null)return;using(var picker=new ColorDialog()){if(picker.ShowDialog(this)==DialogResult.OK)grid.CurrentRow.Cells[2].Value=ColorTranslator.ToHtml(picker.Color);}}));foreach(int step in new[]{-1,1}){int direction=step;tools.Controls.Add(Theme.Button(direction<0?"위로":"아래로",(s,e)=>{if(grid.CurrentRow==null)return;int i=grid.CurrentRow.Index,j=i+direction;if(j<0||j>=grid.Rows.Count)return;var values=grid.Rows[i].Cells.Cast<DataGridViewCell>().Select(x=>x.Value).ToArray();grid.Rows.RemoveAt(i);grid.Rows.Insert(j,values);grid.CurrentCell=grid.Rows[j].Cells[1];}));}tools.Controls.Add(Theme.Button("저장",(s,e)=>{try{grid.EndEdit();var deleted=draft.CategorySettings.Where(x=>x.deleted).ToList();draft.CategorySettings=grid.Rows.Cast<DataGridViewRow>().Select(x=>new CategoryDefinition{name=Convert.ToString(x.Cells[0].Value),label=Convert.ToString(x.Cells[1].Value).Trim(),color=Convert.ToString(x.Cells[2].Value),hidden=Convert.ToBoolean(x.Cells[3].Value)}).ToList();draft.CategorySettings.AddRange(deleted);CategoryCatalog.Validate(draft);Result=draft.CategorySettings;DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message);}},true));Theme.Apply(this);}
 }
}
